class Solution {
public:
    vector<int> decompressRLElist(vector<int>& nums) {
        vector<int> result;
        int n = nums.size();
        int total = 0;
        for (int i = 0; i < n; i += 2) {
            total += nums[i];
        }
        result.reserve(total);
        for (int i = 0; i < n; i += 2) {
            result.insert(result.end(), nums[i], nums[i + 1]);
        }
        return result;
    }
};
